post("/orders") {
    val req = call.receive<PlaceOrderRequest>()
    val orderId = transaction {                    // commit on return, rollback on throw
        val stock = StockTable.selectAll().where { StockTable.id eq req.productId }.single()
        if (stock[StockTable.available] < req.qty) throw ConflictException("insufficient stock")
        StockTable.update({ StockTable.id eq req.productId }) {
            it[available] = stock[StockTable.available] - req.qty
        }
        OrdersTable.insert { it[productId] = req.productId; it[qty] = req.qty } get OrdersTable.id
    }
    call.respond(HttpStatusCode.Created, orderId)
}
